-- StreamPlus (Lite) for MySQL 8.x
-- How to run: MySQL Workbench > connect to localhost > File > Open SQL Script >
-- choose this file > click the lightning-bolt (Execute) button. Takes a few seconds.
-- It creates the database `streamplus_lite` and two tables inside it. Nothing else is touched.

CREATE DATABASE IF NOT EXISTS streamplus_lite CHARACTER SET utf8mb4;
USE streamplus_lite;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS payments;
DROP TABLE IF EXISTS customers;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE customers (
  customer_id          INT          NOT NULL PRIMARY KEY,
  customer_name        VARCHAR(60)  NOT NULL,
  city                 VARCHAR(40)  NOT NULL,
  region               VARCHAR(20)  NOT NULL,
  signup_date          DATE         NOT NULL,
  acquisition_channel  VARCHAR(20)  NULL
) ENGINE=InnoDB;

CREATE TABLE payments (
  payment_id      INT           NOT NULL PRIMARY KEY,
  customer_id     INT           NOT NULL,
  plan_id         TINYINT       NOT NULL,
  payment_date    DATE          NOT NULL,
  amount          DECIMAL(10,2) NOT NULL,
  status          VARCHAR(10)   NOT NULL,
  attempt_no      TINYINT       NOT NULL,
  payment_method  VARCHAR(10)   NOT NULL,
  FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
  INDEX idx_pay_customer (customer_id),
  INDEX idx_pay_date (payment_date)
) ENGINE=InnoDB;

SET autocommit = 0;


COMMIT;

-- Check: expect customers 5157, payments 40360
SELECT 'customers' AS tbl, COUNT(*) AS n FROM customers
UNION ALL SELECT 'payments', COUNT(*) FROM payments;